def table_result(result):
 lines=['|档位|agent行|gold行|仅agent键中的行|仅gold键中的行|共同键不同整行/最少对数|共同键额外行 A/G|全键不匹配行出现 A/G|含键整表匹配|只比较值列匹配|','|---|---:|---:|---:|---:|---:|---|---|---|---|']
 for r in result['levels']:
  lines.append(f"|{r['level']}|{r['agent_rows']}|{r['gold_rows']}|{r['agent_only_key_rows']}|{r['gold_only_key_rows']}|{r['common_key_different_rows_or_min_pairs']}|{r.get('common_key_agent_excess_rows','—')}/{r.get('common_key_gold_excess_rows','—')}|{r.get('key_aware_agent_unmatched','—')}/{r.get('key_aware_gold_unmatched','—')}|{r['whole_match']}|{r.get('value_only_whole_match',r['whole_match'])}|")
 lines+=['',f"含键整表首次匹配档位：**{result['first_match'] or 'L0–L3均未匹配'}**。",'', '|比较列|L0|L1|L2|L3|','|---|---:|---:|---:|---:|']
 for col in result['levels'][0]['column_mismatches']:lines.append('|'+col+'|'+'|'.join(str(r['column_mismatches'][col]) for r in result['levels'])+'|')
 return '\n'.join(lines)

